function setCacheHeaders(res, status, body) {
  res.statusCode = status;
  // give every page the same caching policy
  res.setHeader(
    'Cache-Control',
    'public, max-age=60, stale-while-revalidate=30'
  );
  // small extra TTL on errors so we don't hammer origin
  if (status >= 500) {
    res.setHeader('Cache-Control', 'public, max-age=10');
  }
  res.end(body);
}
